WITH car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm,a.id_imovel,a.id_municipio,a.area FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_municipio='2929701' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2,3),links AS (SELECT p.ano_emissao,p.id_referencia_bacen,p.numero_ordem,p.id_car_norm,c.id_imovel,c.area FROM p JOIN car c USING(id_car_norm)),mixed AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem FROM links GROUP BY 1,2,3 HAVING COUNTIF(area<0.1)>0 AND COUNTIF(area>=1)>0),dp AS (SELECT DISTINCT chave,valor FROM `basedosdados.br_bcb_sicor.dicionario` WHERE nome_coluna='id_programa') SELECT m.ano_emissao,m.id_referencia_bacen,m.numero_ordem,op.data_emissao,COUNT(DISTINCT l.id_imovel) imoveis_vinculados,COUNT(DISTINCT IF(l.area<0.1,l.id_imovel,NULL)) micro_cars,COUNT(DISTINCT IF(l.area>=1,l.id_imovel,NULL)) imoveis_maiores,STRING_AGG(DISTINCT FORMAT('%.4f ha',l.area),', ' ORDER BY FORMAT('%.4f ha',l.area)) areas_declaradas,op.valor_parcela_credito credito_original,n.n_imoveis,SAFE_DIVIDE(op.valor_parcela_credito,n.n_imoveis) credito_rateado_por_imovel,op.area_financiada,COALESCE(e.produto,'(sem produto)') produto,COALESCE(e.finalidade,'(sem finalidade)') finalidade,COALESCE(dp.valor,CONCAT('código ',op.id_programa)) programa,i.nome instituicao FROM mixed m JOIN links l USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN n USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) LEFT JOIN `basedosdados.br_bcb_sicor.empreendimento` e USING(id_empreendimento) LEFT JOIN dp ON dp.chave=op.id_programa LEFT JOIN `basedosdados.br_bcb_sicor.instituicao_financeira` i ON i.cnpj_basico=op.cnpj_basico_instituicao_financeira GROUP BY 1,2,3,4,op.valor_parcela_credito,n.n_imoveis,op.area_financiada,e.produto,e.finalidade,dp.valor,op.id_programa,i.nome ORDER BY op.data_emissao,m.id_referencia_bacen,m.numero_ordem